-- Customer baseline parity: Special Commerce Wave 3 Drop / Release authority.
create unique index if not exists product_variants_id_product_instance_uidx on public.product_variants(id,product_id,instance_id);
create table if not exists public.release_definitions(id uuid primary key default gen_random_uuid(),instance_id uuid not null references public.webshop_instances(id) on delete cascade,release_key text not null check(release_key ~ '^[a-z0-9]+([._-][a-z0-9]+)*$'),title text not null check(char_length(trim(title)) between 1 and 200),summary text,starts_at timestamptz not null,ends_at timestamptz,active boolean not null default true,created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at is null or ends_at>starts_at),unique(instance_id,release_key),unique(instance_id,id));
create table if not exists public.release_items(id uuid primary key default gen_random_uuid(),instance_id uuid not null,release_id uuid not null,item_key text not null check(item_key ~ '^[a-z0-9]+([._-][a-z0-9]+)*$'),product_id uuid not null,variant_id uuid not null,label text check(label is null or char_length(trim(label)) between 1 and 200),sort_order integer not null default 0 check(sort_order between 0 and 1000),created_at timestamptz not null default now(),unique(instance_id,release_id,item_key),unique(instance_id,release_id,variant_id),foreign key(instance_id,release_id) references public.release_definitions(instance_id,id) on delete cascade,foreign key(product_id,instance_id) references public.products(id,instance_id) on delete restrict,foreign key(variant_id,product_id,instance_id) references public.product_variants(id,product_id,instance_id) on delete restrict);
create index if not exists release_definitions_instance_active_start_idx on public.release_definitions(instance_id,active,starts_at);create index if not exists release_definitions_created_by_idx on public.release_definitions(created_by) where created_by is not null;create index if not exists release_definitions_updated_by_idx on public.release_definitions(updated_by) where updated_by is not null;create index if not exists release_items_release_fk_idx on public.release_items(instance_id,release_id,sort_order);create index if not exists release_items_product_instance_fk_idx on public.release_items(product_id,instance_id);create index if not exists release_items_variant_product_instance_fk_idx on public.release_items(variant_id,product_id,instance_id);
alter table public.release_definitions enable row level security;alter table public.release_items enable row level security;revoke all on public.release_definitions from public,anon,authenticated;revoke all on public.release_items from public,anon,authenticated;revoke insert,update,delete on public.release_definitions from service_role;revoke insert,update,delete on public.release_items from service_role;grant select on public.release_definitions to service_role;grant select on public.release_items to service_role;
create or replace function public.save_release_commerce_v1(p_instance_id uuid,p_actor uuid,p_release jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_id uuid;v_key text;v_title text;v_start timestamptz;v_end timestamptz;v_item jsonb;v_product uuid;v_variant uuid;v_label text;v_index integer:=0;begin if not public.can_manage_catalog(p_instance_id,p_actor) then raise exception 'RELEASE_COMMERCE_FORBIDDEN';end if;if p_release is null or pg_catalog.jsonb_typeof(p_release)<>'object' then raise exception 'RELEASE_COMMERCE_DOCUMENT_INVALID';end if;if pg_catalog.octet_length(p_release::text)>1048576 then raise exception 'RELEASE_COMMERCE_DOCUMENT_TOO_LARGE';end if;v_key=trim(coalesce(p_release->>'releaseKey',''));v_title=trim(coalesce(p_release->>'title',''));if v_key !~ '^[a-z0-9]+([._-][a-z0-9]+)*$' or char_length(v_title) not between 1 and 200 then raise exception 'RELEASE_COMMERCE_IDENTITY_INVALID';end if;begin v_start=(p_release->>'startsAt')::timestamptz;v_end=nullif(p_release->>'endsAt','')::timestamptz;exception when others then raise exception 'RELEASE_COMMERCE_WINDOW_INVALID';end;if v_end is not null and v_end<=v_start then raise exception 'RELEASE_COMMERCE_WINDOW_INVALID';end if;if pg_catalog.jsonb_typeof(coalesce(p_release->'items','[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_release->'items','[]'::jsonb)) not between 1 and 100 then raise exception 'RELEASE_COMMERCE_ITEMS_INVALID';end if;insert into public.release_definitions(instance_id,release_key,title,summary,starts_at,ends_at,active,created_by,updated_by) values(p_instance_id,v_key,v_title,nullif(trim(coalesce(p_release->>'summary','')),''),v_start,v_end,coalesce((p_release->>'active')::boolean,true),p_actor,p_actor) on conflict(instance_id,release_key) do update set title=excluded.title,summary=excluded.summary,starts_at=excluded.starts_at,ends_at=excluded.ends_at,active=excluded.active,updated_by=excluded.updated_by,updated_at=now() returning id into v_id;delete from public.release_items where instance_id=p_instance_id and release_id=v_id;for v_item in select value from jsonb_array_elements(p_release->'items') loop if coalesce(v_item->>'itemId','') !~ '^[a-z0-9]+([._-][a-z0-9]+)*$' then raise exception 'RELEASE_COMMERCE_ITEM_ID_INVALID';end if;begin v_product=(v_item->>'productId')::uuid;v_variant=(v_item->>'variantId')::uuid;exception when others then raise exception 'RELEASE_COMMERCE_CATALOG_ID_INVALID';end;v_label=nullif(trim(coalesce(v_item->>'label','')),'');if v_label is not null and char_length(v_label)>200 then raise exception 'RELEASE_COMMERCE_ITEM_LABEL_INVALID';end if;if not exists(select 1 from public.product_variants pv join public.products p on p.id=pv.product_id and p.instance_id=pv.instance_id where pv.instance_id=p_instance_id and pv.id=v_variant and pv.product_id=v_product) then raise exception 'RELEASE_COMMERCE_MAPPING_TENANT_MISMATCH';end if;insert into public.release_items(instance_id,release_id,item_key,product_id,variant_id,label,sort_order) values(p_instance_id,v_id,v_item->>'itemId',v_product,v_variant,v_label,v_index);v_index=v_index+1;end loop;return jsonb_build_object('releaseId',v_id,'releaseKey',v_key);end;$$;
create or replace function public.delete_release_commerce_v1(p_instance_id uuid,p_actor uuid,p_release_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ begin if not public.can_manage_catalog(p_instance_id,p_actor) then raise exception 'RELEASE_COMMERCE_FORBIDDEN';end if;delete from public.release_definitions where instance_id=p_instance_id and id=p_release_id;return found;end;$$;
revoke all on function public.save_release_commerce_v1(uuid,uuid,jsonb) from public,anon,authenticated;revoke all on function public.delete_release_commerce_v1(uuid,uuid,uuid) from public,anon,authenticated;grant execute on function public.save_release_commerce_v1(uuid,uuid,jsonb) to service_role;grant execute on function public.delete_release_commerce_v1(uuid,uuid,uuid) to service_role;
insert into public.entitlement_capabilities(capability_code,release_state,capability_kind,metadata) values('releaseCommerce','released','feature',jsonb_build_object('surface','storefront','family','special-commerce','engine','release-commerce-v1')) on conflict(capability_code) do update set release_state='released',capability_kind='feature',metadata=excluded.metadata,updated_at=now();insert into public.plan_capability_grants(plan_code,capability_code) values('alap','releaseCommerce'),('pro','releaseCommerce') on conflict do nothing;

-- Keep already-provisioned customer tenants aligned with the Block 11 data-driven
-- plan authority after the new Release Commerce grant enters the plan catalog.
do $$
declare r record;
begin
  for r in select id from public.webshop_instances loop
    perform private.sync_webshop_plan_entitlements(r.id);
  end loop;
end $$;
